import sys

def hex_to_int(s):
    return int(s, 16)

def int_to_hex(n, length):
    return format(n, f'0{length}x')

def main():
    S = sys.stdin.read().strip()
    max_perm = hex_to_int(''.join(sorted(S, reverse=True)))
    diff = hex_to_int(S)

    for i in range(max_perm + 1):
        if sorted(int_to_hex(i, len(S))) == sorted(S):
            if i + diff == max_perm:
                print(int_to_hex(i, len(S)))
                return

    print('NO')

main()
